package com.sunmo.stockplatform.analytics.api;
import com.sunmo.stockplatform.analytics.domain.DetectionPerformance;import java.math.BigDecimal;import java.time.Instant;
public final class PerformanceDtos {private PerformanceDtos(){}public record PerformanceResponse(Long detectionId,String stockCode,String status,String calculationVersion,BigDecimal detectedPrice,BigDecimal price5m,BigDecimal price10m,BigDecimal price30m,BigDecimal price60m,BigDecimal closePrice,BigDecimal return5m,BigDecimal return10m,BigDecimal return30m,BigDecimal return60m,BigDecimal returnClose,BigDecimal highestPrice,BigDecimal lowestPrice,BigDecimal maxReturn,BigDecimal maxDrawdown,BigDecimal mfe,BigDecimal mae,Instant observed5mAt,Instant observed10mAt,Instant observed30mAt,Instant observed60mAt,Instant closeObservedAt,boolean recoveryUsed,String finalizationReason,Instant finalizedAt){public static PerformanceResponse from(DetectionPerformance p){return new PerformanceResponse(p.getDetectionId(),p.getDetection().getStock().getStockCode(),p.getStatus().name(),p.getCalculationVersion(),p.getDetection().getDetectedPrice(),p.getPrice5m(),p.getPrice10m(),p.getPrice30m(),p.getPrice60m(),p.getClosePrice(),p.getReturn5m(),p.getReturn10m(),p.getReturn30m(),p.getReturn60m(),p.getReturnClose(),p.getHighestPrice(),p.getLowestPrice(),p.getMaxReturn(),p.getMaxDrawdown(),p.getMfe(),p.getMae(),p.getObserved5mAt(),p.getObserved10mAt(),p.getObserved30mAt(),p.getObserved60mAt(),p.getCloseObservedAt(),p.isRecoveryUsed(),p.getFinalizationReason(),p.getFinalizedAt());}}public record AnalyticsResponse(long total,long completed,long dataMissing,BigDecimal winRate5m,BigDecimal winRateClose,BigDecimal averageReturn5m,BigDecimal averageReturn10m,BigDecimal averageReturn30m,BigDecimal averageReturn60m,BigDecimal averageReturnClose,String calculationVersion) {}}
